<script nonce="<?php echo $nonce; ?>">
// ── Auto-enter: a calm splash, a soft fade, then straight in ──
(function(){
    var target = <?php echo json_encode($target); ?>;
    var go = false;

    function enter(){
        if (go) return;
        go = true;
        document.body.classList.add('leaving');
        setTimeout(function(){ location.replace(target); }, 500);
    }

    var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
    setTimeout(enter, reduce ? 500 : 4000);

    // tap or click anywhere to skip right away
    document.getElementById('splash').addEventListener('click', function(e){
        e.preventDefault();
        enter();
    });
})();

// ── Back/forward cache: never show a faded-out splash ──
window.addEventListener('pageshow', function(e){
    if (e.persisted) location.reload();
});
</script>
